  ('lar-residencia-senior-dos-jacarandas', true, true, 'Residência Sénior dos Jacarandás', 'residencia', 'privado', 'Residência sénior de tipo hoteleiro com enfermagem 24 horas, na Ribeira Grande.', E'Inaugurada em 2020, a Residência Sénior dos Jacarandás oferece 73 lugares em quartos e suites com casa de banho privativa, pensada para quem quer manter a independência com a segurança de uma equipa sempre presente.\n\nA equipa de saúde inclui enfermagem 24 horas (8 enfermeiros), médico assistente semanal, fisioterapia e psicologia. Cada residente tem um plano individual de cuidados, revisto com a família a cada seis meses.\n\nO dia a dia inclui expressão plástica, missa semanal e refeições confecionadas na própria cozinha. As visitas são diárias, em horário alargado.', 'Rua da Quinta, 78', '9600-863', 'Ribeira Grande', 'Ribeira Grande', 'Açores', 'Açores', 37.815, -25.52, '296 000 260', 'geral@residencia-senior-dos-jacara.exemplo.pt', null, 73, 1, 38, false, array['Alojamento e todas as refeições', 'Higiene pessoal e apoio diário', 'Tratamento de roupa', 'Administração da medicação', 'Enfermagem 24 horas', 'Animação sociocultural']::text[], '[{"nome":"Fraldas e produtos de incontinência","preco":"a partir de 60 €/mês"},{"nome":"Consultas de especialidade","preco":"conforme tabela"},{"nome":"Fisioterapia individual (sessões extra)","preco":"25 € por sessão"},{"nome":"Acompanhamento a consultas externas","preco":"15 € por hora"}]'::jsonb, array['autonomo', 'ligeira', 'moderada']::public.grau_dependencia[], array['enfermagem24h', 'medico', 'fisioterapia', 'diabetes', 'terapia_ocupacional', 'psicologia', 'nutricao']::text[], array['quarto_wc', 'climatizacao', 'wifi', 'atividades', 'animais', 'lavandaria', 'cozinha_propria', 'capela']::text[], 3.8, 8, 5, '787/2022', 'verificado', now() - interval '15552000 seconds', now() - interval '40262400 seconds', 3.7, 85, 2020, now() - interval '381600 seconds', '{"hue":194,"variante":2}'::jsonb, 564),
  ('lar-casa-de-repouso-do-pinhal', true, true, 'Casa de Repouso do Pinhal', 'erpi', 'privado', 'Espaço tranquilo com enfermagem 24 horas, em Angra do Heroísmo.', E'Fundada em 2012, a Casa de Repouso do Pinhal acolhe 58 residentes em Angra do Heroísmo. É uma instituição privada com licença de funcionamento emitida pela Segurança Social.\n\nA equipa de saúde inclui enfermagem 24 horas (7 enfermeiros), médico assistente semanal e psicologia. Cada residente tem um plano individual de cuidados, revisto com a família sempre que há alterações.\n\nO dia a dia inclui expressão plástica, missa semanal e refeições confecionadas na própria cozinha. As visitas são diárias, em horário alargado.', 'Rua Professor Egas Moniz, 262', '9700-382', 'Angra do Heroísmo', 'Angra do Heroísmo', 'Açores', 'Açores', 38.66, -27.22, '295 000 261', 'geral@casa-de-repouso-do-pinhal.exemplo.pt', null, 58, 32, 29, false, array['Alojamento e todas as refeições', 'Higiene pessoal e apoio diário', 'Tratamento de roupa', 'Administração da medicação', 'Enfermagem 24 horas', 'Animação sociocultural']::text[], '[{"nome":"Fraldas e produtos de incontinência","preco":"a partir de 60 €/mês"},{"nome":"Consultas de especialidade","preco":"conforme tabela"},{"nome":"Acompanhamento a consultas externas","preco":"15 € por hora"}]'::jsonb, array['autonomo', 'ligeira', 'moderada', 'grave']::public.grau_dependencia[], array['enfermagem24h', 'medico', 'diabetes', 'oxigenio', 'psicologia', 'acamados']::text[], array['climatizacao', 'atividades', 'lavandaria', 'cozinha_propria', 'capela']::text[], 4.4, 7, 5, '210/2013', 'pendente', null, now() - interval '12182400 seconds', 4, 85, 2012, now() - interval '1537200 seconds', '{"hue":233,"variante":1}'::jsonb, 1137)
